package au.aumanet.app;
import java.net.*;import java.security.*;import java.security.spec.*;import java.util.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Actual production exchange and real localhost UDP/P256; Android Network binding
 * and the checked field-context guard are explicit fixture boundaries. */
public final class GatewayRadioExchangeTest {
 static void reservationPort()throws Exception{
  KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));KeyPair node=g.generateKeyPair();GatewayLeaseIssuer.signing=g.generateKeyPair();SystemClock.real=true;
  try(DatagramSocket server=new DatagramSocket(new InetSocketAddress(InetAddress.getLoopbackAddress(),0))){
   server.setSoTimeout(5000);AtomicReference<Throwable> failed=new AtomicReference<>();AtomicInteger commands=new AtomicInteger();
   Thread responder=new Thread(()->{try{SocketAddress reserved=null;for(int i=0;i<2;i++){
    byte[] buffer=new byte[322];DatagramPacket p=new DatagramPacket(buffer,buffer.length);server.receive(p);GatewayRadioConfigCodec.Frame f=GatewayRadioConfigCodec.frame(buffer,p.getLength());if(!f.verify(GatewayLeaseIssuer.signing.getPublic()))throw new AssertionError();
    if(i==0){if(f.message.kind!='Q')throw new AssertionError();reserved=p.getSocketAddress();}
    else{if(f.message.kind!='C'||!reserved.equals(p.getSocketAddress()))throw new AssertionError("Command changed the reserved source port");commands.incrementAndGet();}
    GatewayRadioConfigCodec.Message report=GatewayRadioSettingsTest.report(false,GatewayRadioSettingsTest.RUN,i==0?0:3,i==0?5:22,5,7,i==0?"0".repeat(32):GatewayRadioSettingsTest.TX);
    Signature sign=Signature.getInstance("SHA256withECDSA");sign.initSign(node.getPrivate());sign.update(report.body());byte[] bytes=GatewayRadioConfigCodec.envelope(report,sign.sign());server.send(new DatagramPacket(bytes,bytes.length,p.getSocketAddress()));
   }}catch(Throwable failure){failed.set(failure);}});responder.setDaemon(true);responder.start();
   new GatewayRadioExchangeHarness(server.getLocalPort()).queryThenTrial(node.getPublic());responder.join(2000);check(!responder.isAlive());check(failed.get()==null);check(commands.get()==1);
  }finally{SystemClock.real=false;}
 }
 static int assertions;static void check(boolean b){assertions++;if(!b)throw new AssertionError("Radio query latency regression");}
 static void delayed(int delay,boolean expected)throws Exception{delayed(delay,expected,false);} static void delayed(int delay,boolean expected,boolean command)throws Exception{
  KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));KeyPair node=g.generateKeyPair();GatewayLeaseIssuer.signing=g.generateKeyPair();SystemClock.real=true;
  try(DatagramSocket server=new DatagramSocket(new InetSocketAddress(InetAddress.getLoopbackAddress(),0))){server.setSoTimeout(5000);AtomicReference<Throwable> failed=new AtomicReference<>();Thread responder=new Thread(()->{try{byte[] b=new byte[322];DatagramPacket p=new DatagramPacket(b,b.length);server.receive(p);GatewayRadioConfigCodec.Frame request=GatewayRadioConfigCodec.frame(b,p.getLength());if(request.message.kind!=(command?'C':'Q'))throw new AssertionError();Thread.sleep(delay);GatewayRadioConfigCodec.Message report=GatewayRadioSettingsTest.report(false,GatewayRadioSettingsTest.RUN,0,5,0,0,"0".repeat(32));Signature s=Signature.getInstance("SHA256withECDSA");s.initSign(node.getPrivate());s.update(report.body());byte[] reply=GatewayRadioConfigCodec.envelope(report,s.sign());server.send(new DatagramPacket(reply,reply.length,p.getSocketAddress()));}catch(Throwable t){failed.set(t);}});responder.setDaemon(true);responder.start();
   GatewayRadioExchangeHarness h=new GatewayRadioExchangeHarness(server.getLocalPort());boolean accepted=false;long began=System.nanoTime();try{if(command)h.commit(node.getPublic());else h.query(node.getPublic());accepted=true;}catch(SocketTimeoutException expired){}long elapsed=(System.nanoTime()-began)/1000000;responder.join(6000);check(!responder.isAlive()&&failed.get()==null);check(accepted==expected);if(expected){check(elapsed>=2000&&elapsed<4000);check(h.logs.stream().anyMatch(x->x.contains("stage=ACCEPTED")));}else{check(elapsed>=4000&&elapsed<4500);check(h.logs.stream().anyMatch(x->x.contains("reason=NO_REPLY")));}
  }finally{SystemClock.real=false;}
 }
 static void changedBootAtExpiry()throws Exception{KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));KeyPair node=g.generateKeyPair();GatewayLeaseIssuer.signing=g.generateKeyPair();SystemClock.real=true;try(DatagramSocket server=new DatagramSocket(new InetSocketAddress(InetAddress.getLoopbackAddress(),0))){server.setSoTimeout(5000);Thread reply=new Thread(()->{try{byte[] b=new byte[322];DatagramPacket p=new DatagramPacket(b,b.length);server.receive(p);GatewayRadioConfigCodec.Message report=GatewayRadioSettingsTest.report(false,"7".repeat(32),0,5,0,0,"0".repeat(32));Signature sign=Signature.getInstance("SHA256withECDSA");sign.initSign(node.getPrivate());sign.update(report.body());byte[] bytes=GatewayRadioConfigCodec.envelope(report,sign.sign());server.send(new DatagramPacket(bytes,bytes.length,p.getSocketAddress()));}catch(Exception failed){throw new IllegalStateException(failed);}});reply.setDaemon(true);reply.start();GatewayRadioExchangeHarness h=new GatewayRadioExchangeHarness(server.getLocalPort());java.security.interfaces.ECPublicKey key=(java.security.interfaces.ECPublicKey)node.getPublic();java.security.interfaces.ECPublicKey timed=new java.security.interfaces.ECPublicKey(){public ECParameterSpec getParams(){return key.getParams();}public ECPoint getW(){return key.getW();}public String getAlgorithm(){return key.getAlgorithm();}public String getFormat(){return key.getFormat();}public byte[] getEncoded(){h.issuer.strict=()->false;return key.getEncoded();}};boolean rejected=false;try{h.query(timed,true);}catch(SecurityException expected){check(!(expected instanceof GatewayRadioQueryPolicy.FreshnessUnavailable));rejected=true;}reply.join(2000);check(rejected);check(h.logs.stream().anyMatch(x->x.contains("wrongBoot=1")&&x.contains("stage=BOOT")));}finally{SystemClock.real=false;}}
 public static void main(String[] args)throws Exception{check(GatewayRadioQueryPolicy.receiving(true,100,4099));check(!GatewayRadioQueryPolicy.receiving(true,100,4100));check(GatewayRadioQueryPolicy.receiving(false,100,4099));check(!GatewayRadioQueryPolicy.receiving(false,100,4100));check(!GatewayRadioQueryPolicy.receiving(true,100,99));check(GatewayRadioQueryPolicy.stationFirst(Arrays.asList(GatewayRadioSettingsTest.A,GatewayRadioSettingsTest.B),GatewayRadioSettingsTest.A).equals(Arrays.asList(GatewayRadioSettingsTest.B,GatewayRadioSettingsTest.A)));check(GatewayRadioQueryPolicy.stationFirst(Arrays.asList(GatewayRadioSettingsTest.B,GatewayRadioSettingsTest.A),GatewayRadioSettingsTest.A).get(1).equals(GatewayRadioSettingsTest.A));delayed(2300,true);delayed(4300,false);delayed(2300,true,true);delayed(4300,false,true);changedBootAtExpiry();reservationPort();System.out.println(new JSONObject().put("status","pass").put("testCount",7).put("assertionCount",assertions));}
}
